sp_widget.client_script:
api.controller=function() {
 /* widget controller */
  var c = this;

  // Retrieve message passed from spModal.open(widgetInput)
  if (c.options && c.options.widgetInput && c.options.widgetInput.message) {
    c.data.message = c.options.widgetInput.message;
  } else if (c.data.message) { // In case it's set via server script default
      // Already populated
  } else {
      c.data.message = 'Loading...'; // Default message if none provided
  }
};

sp_widget.css:
.panel-body {
  padding: 30px; /* Adds space around the content */
}

.loading-message {
  font-size: 1.2em; /* Slightly larger text for the message */
  font-weight: bold;
  margin-bottom: 15px;
  color: #333; /* A neutral dark color */
}

.loading-hint {
  font-size: 0.9em;
  color: #666;
  margin-top: 10px;
}

