     box-shadow: var(--now-shadow--sm);
     border-radius: var(--now-border-radius--lg);
   }

   If your HSBC theme defines a specific color for progress bars:
*/

/* Example of custom HSBC styling for progress bar (modify as per your theme) */
.hsbc-progress-bar {
  background-color: #e0e0e0; /* Light gray background for the bar container */
  height: 25px; /* Thicker bar */
  border-radius: 5px; /* Slightly rounded corners */
  overflow: hidden; /* Ensure inner bar stays within bounds */
}

.hsbc-progress-bar-inner {
  background-color: #DA291C; /* Example: HSBC Red, replace with your exact color */
  /* Add other HSBC specific styling for the progress bar fill */
}

